var _seerahCat='مكة المكرمة';

function buildSeerah(){
  var catsEl=document.getElementById('seerah-cats');
  var tl=document.getElementById('seerah-timeline');
  if(!catsEl||!tl)return;
  if(!catsEl.children.length){
    Object.keys(SEERAH_DATA).forEach(function(cat){
      var btn=document.createElement('button');
      btn.textContent=(cat==='مكة المكرمة'?'🕋 ':'🕌 ')+cat;
      btn.style.cssText='background:rgba(201,168,76,'+(cat===_seerahCat?'.2':'.07')+');border:1px solid rgba(201,168,76,'+(cat===_seerahCat?'.5':'.2')+');color:'+(cat===_seerahCat?'#f0d080':'var(--tm)')+';padding:.5rem 1.1rem;border-radius:50px;font-family:Tajawal,sans-serif;font-size:.88rem;cursor:pointer;transition:all .25s;';
      btn.dataset.cat=cat;
      btn.onclick=function(){
        _seerahCat=cat;
        catsEl.querySelectorAll('button').forEach(function(b){
          var active=b.dataset.cat===cat;
          b.style.background=active?'rgba(201,168,76,.2)':'rgba(201,168,76,.07)';
          b.style.borderColor=active?'rgba(201,168,76,.5)':'rgba(201,168,76,.2)';
          b.style.color=active?'#f0d080':'var(--tm)';
        });
        renderSeerahTimeline();
      };
      catsEl.appendChild(btn);
    });
  }
  renderSeerahTimeline();
}

function renderSeerahTimeline(){
  var tl=document.getElementById('seerah-timeline');
  if(!tl)return;
  var events=SEERAH_DATA[_seerahCat]||[];
  var html='<div style="position:relative;padding-right:1.5rem;">';
  // خط زمني
  html+='<div style="position:absolute;right:.7rem;top:0;bottom:0;width:2px;background:linear-gradient(to bottom,rgba(201,168,76,.6),rgba(201,168,76,.1));"></div>';
  events.forEach(function(ev,i){
    html+='<div style="position:relative;margin-bottom:1.2rem;">'
      // نقطة على الخط
      +'<div style="position:absolute;right:-.85rem;top:.8rem;width:14px;height:14px;background:#C9A84C;border-radius:50%;border:2px solid #030A06;box-shadow:0 0 8px rgba(201,168,76,.5);"></div>'
      // بطاقة الحدث
      +'<div style="background:rgba(13,59,46,.4);border:1px solid rgba(201,168,76,.18);border-radius:14px;padding:1rem 1.1rem;cursor:pointer;transition:all .25s;" onclick="this.querySelector(\'.seerah-detail\').style.display=this.querySelector(\'.seerah-detail\').style.display===\'none\'?\'block\':\'none\'">'
      +'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:.3rem;">'
      +'<div style="display:flex;align-items:center;gap:.5rem;">'
      +'<span style="font-size:1.2rem">'+ev.icon+'</span>'
      +'<span style="font-family:\'Scheherazade New\',serif;font-size:1.05rem;color:#f0d080;">'+ev.title+'</span>'
      +'</div>'
      +'<span style="font-size:.72rem;color:var(--gold);background:rgba(201,168,76,.1);padding:.2rem .5rem;border-radius:8px;">'+ev.year+'</span>'
      +'</div>'
      +'<div class="seerah-detail" style="display:none;font-size:.85rem;color:var(--tm);line-height:1.8;margin-top:.5rem;padding-top:.5rem;border-top:1px solid rgba(201,168,76,.1);">'+ev.text+'</div>'
      +'</div></div>';
  });
  html+='</div>';
  tl.innerHTML=html;
}

