function buildMosques(){
  var list = document.getElementById('mosques-list');
  if (list && !list.dataset.loaded) {
    list.dataset.loaded = '1';
    setTimeout(function(){ try { locateMosques(); } catch(e){} }, 350);
  }
}
function locateMosques(){
  var btn=document.getElementById('mosques-locate-btn');
  var status=document.getElementById('mosques-status');
  var list=document.getElementById('mosques-list');
  var mapLink=document.getElementById('mosques-map-link');
  if(!status)return;
  if(!navigator.geolocation){status.innerHTML='<span style="color:#e87a7a">المتصفح لا يدعم تحديد الموقع</span>';return;}
  if(btn){ btn.disabled=true; }
  status.innerHTML='<div style="color:var(--gold)">جارٍ تحديد موقعك...</div>';
  if(list) list.innerHTML='';
  function hav(lat1,lon1,lat2,lon2){
    var R=6371000, tr=Math.PI/180;
    var dLat=(lat2-lat1)*tr, dLon=(lon2-lon1)*tr;
    var a=Math.sin(dLat/2)**2+Math.cos(lat1*tr)*Math.cos(lat2*tr)*Math.sin(dLon/2)**2;
    return Math.round(R*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a)));
  }
  function render(lat,lng,elements){
    var items=[];
    (elements||[]).forEach(function(el){
      var c=el.center||{};
      var mlat=el.lat||c.lat, mlng=el.lon||c.lon;
      if(mlat==null||mlng==null) return;
      var tags=el.tags||{};
      items.push({name:tags['name:ar']||tags.name||tags['name:en']||'مسجد',lat:mlat,lng:mlng,dist:hav(lat,lng,mlat,mlng)});
    });
    items.sort(function(a,b){return a.dist-b.dist;});
    if(!items.length){
      status.innerHTML='<div style="color:var(--tm)">لم يُعثر على مساجد — جرّب مرة أخرى أو افتح الخريطة</div>';
      if(btn) btn.disabled=false;
      return;
    }
    status.innerHTML='<div style="color:#7ae87a">وُجد '+items.length+' مسجد قريب</div>';
    var html='';
    items.slice(0,20).forEach(function(m){
      var d=m.dist>=1000?(m.dist/1000).toFixed(1)+' كم':m.dist+' م';
      html+='<div style="background:rgba(13,59,46,.4);border:1px solid rgba(201,168,76,.15);border-radius:12px;padding:.9rem 1rem;margin-bottom:.5rem;display:flex;justify-content:space-between;align-items:center;cursor:pointer" onclick="window.open(\'https://www.google.com/maps/dir/?api=1&destination='+m.lat+','+m.lng+'\',\'_blank\')"><div><div style="font-family:Scheherazade New,serif;font-size:1rem;color:#f0d080;">🕌 '+m.name+'</div><div style="font-size:.72rem;color:var(--tm);margin-top:.2rem;">'+d+' — اضغط للاتجاهات</div></div><span style="color:var(--gold)">↗</span></div>';
    });
    if(list) list.innerHTML=html;
    if(mapLink){ mapLink.href='https://www.google.com/maps/search/mosque/@'+lat+','+lng+',15z'; mapLink.style.display='block'; }
    if(btn) btn.disabled=false;
  }
  function q(lat,lng,r){
    var qq='[out:json][timeout:25];(node["amenity"="place_of_worship"]["religion"="muslim"](around:'+r+','+lat+','+lng+');way["amenity"="place_of_worship"]["religion"="muslim"](around:'+r+','+lat+','+lng+');node["building"="mosque"](around:'+r+','+lat+','+lng+');way["building"="mosque"](around:'+r+','+lat+','+lng+'););out center 30;';
    return fetch('https://overpass-api.de/api/interpreter',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'data='+encodeURIComponent(qq)}).then(function(r){return r.json();});
  }
  navigator.geolocation.getCurrentPosition(function(pos){
    var lat=pos.coords.latitude, lng=pos.coords.longitude;
    status.innerHTML='<div style="color:var(--gold)">جارٍ البحث عن المساجد...</div>';
    q(lat,lng,2500).then(function(data){
      var els=data.elements||[];
      if(els.length){ render(lat,lng,els); return null; }
      return q(lat,lng,6000);
    }).then(function(data){ if(data) render(lat,lng,data.elements||[]); }).catch(function(){
      status.innerHTML='<div style="color:#e87a7a">تعذّر الاتصال — افتح الخرائط يدويًا</div>';
      if(mapLink){ mapLink.href='https://www.google.com/maps/search/mosque/@'+lat+','+lng+',15z'; mapLink.style.display='block'; }
      if(btn) btn.disabled=false;
    });
  }, function(err){
    var msg='تعذّر تحديد الموقع';
    if(err&&err.code===1) msg='اسمح بإذن الموقع من إعدادات التطبيق (الموقع / Location)';
    status.innerHTML='<span style="color:#e87a7a">'+msg+'</span>';
    if(btn) btn.disabled=false;
  }, {enableHighAccuracy:true, timeout:20000, maximumAge:15000});
}

function buildRamadan(){
  var box=document.getElementById('ramadan-main');
  if(!box)return;
  var now=new Date();
  var h=gregorianToHijri(now.getFullYear(),now.getMonth()+1,now.getDate());
  var isRamadan=(h.m===9);
  var daysToRamadan=0;
  if(!isRamadan){
    // حساب الأيام للرمضان القادم
    var nextRamadanMonth=9;
    var nextRamadanYear=h.m>=9?h.y+1:h.y;
    daysToRamadan=(nextRamadanMonth-h.m)*30+(1-h.d);
    if(daysToRamadan<0)daysToRamadan+=354;
  }
  var html='';
  if(isRamadan){
    var remaining=30-h.d;
    html='<div style="background:linear-gradient(135deg,rgba(201,168,76,.2),rgba(13,59,46,.8));border:1px solid rgba(201,168,76,.35);border-radius:20px;padding:1.5rem;text-align:center;margin-bottom:1rem;">'
      +'<div style="font-size:3rem;margin-bottom:.3rem;">🌙</div>'
      +'<div style="font-family:\'Scheherazade New\',serif;font-size:1.6rem;color:#f0d080;margin-bottom:.2rem;">رمضان المبارك</div>'
      +'<div style="font-size:.85rem;color:var(--tm);">اليوم '+h.d+' من رمضان — تبقّى '+remaining+' يوم</div>'
      +'<div style="background:rgba(0,0,0,.3);border-radius:10px;height:8px;margin:1rem 0;overflow:hidden;">'
      +'<div style="background:#C9A84C;height:100%;width:'+(h.d/30*100)+'%;transition:width .5s;border-radius:8px;"></div></div>'
      +'<div style="font-size:.78rem;color:rgba(201,168,76,.6);">مضى '+(h.d/30*100).toFixed(0)+'٪ من رمضان</div>'
      +'</div>';
  } else {
    html='<div style="background:rgba(13,59,46,.5);border:1px solid rgba(201,168,76,.2);border-radius:20px;padding:1.5rem;text-align:center;margin-bottom:1rem;">'
      +'<div style="font-size:2.5rem;margin-bottom:.5rem;">⏳</div>'
      +'<div style="font-family:\'Scheherazade New\',serif;font-size:1.3rem;color:#f0d080;margin-bottom:.3rem;">العدّ التنازلي لرمضان</div>'
      +'<div style="font-size:2.5rem;color:var(--gold);font-weight:700;margin:.5rem 0;">~'+daysToRamadan+'</div>'
      +'<div style="font-size:.85rem;color:var(--tm);">يوماً تقريباً حتى رمضان القادم</div>'
      +'<div style="font-size:.72rem;color:rgba(201,168,76,.5);margin-top:.5rem;">(الحساب الهجري تقريبي)</div>'
      +'</div>';
  }
  // فضائل رمضان
  html+='<div style="margin-bottom:1rem;">'
    +'<div style="color:var(--gold);font-size:.88rem;font-weight:700;margin-bottom:.6rem;">✨ من فضائل رمضان</div>';
  var fadail=[
    {icon:'🌙',t:'شهر القرآن',s:'شَهْرُ رَمَضَانَ الَّذِي أُنزِلَ فِيهِ الْقُرْآنُ هُدًى لِّلنَّاسِ'},
    {icon:'🔥',t:'تُصفَّد الشياطين',s:'إذا جاء رمضان فتحت أبواب الجنة وغلقت أبواب النار وصُفِّدت الشياطين'},
    {icon:'🌟',t:'ليلة خير من ألف شهر',s:'لَيْلَةُ الْقَدْرِ خَيْرٌ مِّنْ أَلْفِ شَهْرٍ'},
    {icon:'🤲',t:'الدعاء مستجاب',s:'ثلاثة لا تُرد دعوتهم: الصائم حتى يُفطر، والإمام العادل، والمظلوم'},
    {icon:'💰',t:'العمرة كحجة',s:'عمرة في رمضان تعدل حجة أو حجة معي — رواه البخاري ومسلم'}
  ];
  fadail.forEach(function(f){
    html+='<div style="background:rgba(13,59,46,.4);border:1px solid rgba(201,168,76,.12);border-radius:12px;padding:.8rem 1rem;margin-bottom:.5rem;">'
      +'<div style="display:flex;align-items:center;gap:.5rem;margin-bottom:.3rem;">'
      +'<span style="font-size:1.1rem;">'+f.icon+'</span>'
      +'<span style="color:#f0d080;font-size:.9rem;font-weight:700;">'+f.t+'</span></div>'
      +'<div style="font-family:\'Scheherazade New\',serif;font-size:.9rem;color:var(--tm);line-height:1.7;">'+f.s+'</div>'
      +'</div>';
  });
  html+='</div>';
  // نصائح رمضان
  html+='<div style="background:rgba(201,168,76,.06);border:1px solid rgba(201,168,76,.15);border-radius:14px;padding:1rem;">'
    +'<div style="color:var(--gold);font-size:.88rem;font-weight:700;margin-bottom:.6rem;">📋 برنامج مقترح ليوم رمضاني</div>'
    +'<div style="font-size:.82rem;color:var(--tm);line-height:2.1;">'
    +'🌙 السحور: تناول السحور قبل الفجر بربع ساعة<br>'
    +'🌅 الفجر: صلاة الفجر + قراءة جزء من القرآن<br>'
    +'☀️ الضحى: صلاة الضحى 2-8 ركعات<br>'
    +'🕌 الظهر والعصر: المحافظة على الصلوات<br>'
    +'🌅 قبل المغرب: الدعاء في آخر ساعة<br>'
    +'🌙 الإفطار: بتمر وماء ثم الصلاة<br>'
    +'🌟 التراويح: إحياء الليل بالقيام والتلاوة'
    +'</div></div>';
  box.innerHTML=html;
}

// ══════════════════════════════════════════════════
// 👳 قصص الأنبياء الكاملة
// ══════════════════════════════════════════════════
var PROPHETS2=[
  {n:'آدم',e:'Adam',ico:'🌱',s:'أبو البشرية',story:`خلق الله آدم عليه السلام بيديه الكريمتين من طين، من صلصال كالفخار، ثم سوّاه ونفخ فيه من روحه، فكان أول إنسان وأول نبي وخليفة في الأرض. علّمه الأسماء كلها، وعرضها على الملائكة فقال: أنبئوني بأسماء هؤلاء إن كنتم صادقين، فلم يعلموا، وأنبأهم آدم بأسمائها. أمر الله الملائكة بالسجود لآدم تكريمًا، فسجدوا جميعًا إلا إبليس أبى واستكبر وكان من الكافرين.

أسكنه الله الجنة مع زوجه حواء، وأباح لهما الأكل من كل ثمارها إلا شجرة واحدة نهاهما عنها. فوسوس لهما الشيطان وقال: ما نهاكما ربكما عن هذه الشجرة إلا أن تكونا ملكين أو تكونا من الخالدين، وقاسمهما إني لكما لمن الناصحين. فأكلا منها فبدت لهما سوآتهما، فناداهما ربهما: ألم أنهكما عن تلكما الشجرة وأقل لكما إن الشيطان لكما عدو مبين؟

تابا إلى الله فتاب عليهما، وعلّم آدم كلماتٍ فتاب عليه إنه هو التواب الرحيم. ثم أهبطهما إلى الأرض، وقال: اهبطوا بعضكم لبعض عدو، ولكم في الأرض مستقر ومتاع إلى حين. عاش آدم على الأرض يعبد الله ويعلّم ذريته التوحيد، وأنجب قابيل وهابيل. تقرّبا بقربانين فتقبّل من هابيل ولم يُتقبل من قابيل، فقتل قابيل أخاه حسدًا، فكان أول قتل في البشرية. ذُكر آدم في القرآن في مواضع كثيرة، وهو أبو البشر وأبو الأنبياء جميعًا.`,quran:'﴿وَإِذْ قَالَ رَبُّكَ لِلْمَلَائِكَةِ إِنِّي جَاعِلٌ فِي الْأَرْضِ خَلِيفَةً﴾ البقرة: ٣٠'},
  {n:'إدريس',e:'Idris',ico:'📚',s:'النبي الصدّيق',story:`إدريس عليه السلام نبي كريم من أجداد نوح، وهو من الصدّيقينين الصابرين. كان أول من خطّ بالقلم، وأول من خاط الثياب ولبسها، وكان الناس قبله يلبسون الجلود. دعا قومه إلى عبادة الله وحده، وإلى مكارم الأخلاق، وعاش عمرًا طويلًا يعظهم ويذكّرهم.

وصفه الله في القرآن بالصدّيقية والنبوة، ورفعه مكانًا عليًّا. وقد رأى النبي محمد ﷺ إدريس في السماء ليلة الإسراء والمعراج، فسلّم عليه. ذُكر في سورة مريم والأنبياء، وهو مثال للصبر والعلم والدعوة الهادئة. كانت رسالته تجديدًا لملة التوحيد بعد أن بدأ الانحراف يظهر في بني آدم.`,quran:'﴿وَاذْكُرْ فِي الْكِتَابِ إِدْرِيسَ ۚ إِنَّهُ كَانَ صِدِّيقًا نَّبِيًّا ۝ وَرَفَعْنَاهُ مَكَانًا عَلِيًّا﴾ مريم: ٥٦–٥٧'},
  {n:'نوح',e:'Noah',ico:'🚢',s:'شيخ المرسلين',story:`نوح عليه السلام أول الرسل بعد انتشار الشرك في الأرض، وهو من أولي العزم من الرسل. أرسله الله إلى قومه يدعوهم إلى عبادة الله وحده، وترك عبادة الأصنام التي اتخذوها من دون الله: ودًّا وسواعًا ويغوث ويعوق ونسرًا. لبث فيهم ألف سنة إلا خمسين عامًا، يدعوهم ليلًا ونهارًا، سرًّا وجهارًا، فلم يزده دعاؤه إلا فرارًا.

سخر منه أشراف القوم وقالوا: ما نراك إلا بشرًا مثلنا، وما نراك اتبعك إلا الذين هم أراذلنا بادئ الرأي، وما نرى لكم علينا من فضل. فقال نوح: يا قوم ليس بي سفاهة ولكني رسول من رب العالمين. ولما يئس من إيمانهم أوحى الله إليه أنه لن يؤمن من قومك إلا من قد آمن، فاصنع الفلك بأعيننا ووحينا.

فبنى السفينة، وكلما مر عليه ملأ من قومه سخروا منه. ثم جاء أمر الله، وفار التنور، فحمل فيها من كل زوجين اثنين وأهله إلا من سبق عليه القول، ومن آمن. وجاء الطوفان فأغرق الكافرين جميعًا، حتى ابن نوح الذي قال: سآوي إلى جبل يعصمني من الماء، قال: لا عاصم اليوم من أمر الله إلا من رحم. واستوت السفينة على الجودي، وقيل: بعدًا للقوم الظالمين. نجا نوح ومن آمن، وبدأ البشرية مرحلة جديدة على التوحيد.`,quran:'﴿وَلَقَدْ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِ فَلَبِثَ فِيهِمْ أَلْفَ سَنَةٍ إِلَّا خَمْسِينَ عَامًا﴾ العنكبوت: ١٤'},
  {n:'هود',e:'Hud',ico:'💨',s:'نبي عاد',story:`هود عليه السلام أُرسل إلى قوم عاد، وكانوا في الأحقاف، أصحاب أجسام ضخمة وقوة وبنيان شامخ، يقولون: من أشد منا قوة؟ عبدوا الأصنام وتجبروا في الأرض بغير الحق. دعاهم هود إلى عبادة الله وحده، وقال: يا قوم اعبدوا الله ما لكم من إله غيره، أفلا تتقون؟ فكذبوه واتهموه بالسفاهة والجنون.

قالوا: أجئتنا لنعبد الله وحده ونذر ما كان يعبد آباؤنا؟ فأنذرهم بعذاب يوم عظيم. استكبروا وأصرّوا، فأمسك الله عنهم المطر، ثم رأوا سحابًا مقبلًا فحسبوه مطرًا، قال: بل هو ما استعجلتم به، ريح فيها عذاب أليم. دمّر الله عليهم بريح صرصر عاتية سخرها عليهم سبع ليالٍ وثمانية أيام حسومًا، فتترى القوم فيها صرعى كأنهم أعجاز نخل خاوية. ونجّى الله هودًا والذين آمنوا معه برحمة منه.`,quran:'﴿وَأَمَّا عَادٌ فَأُهْلِكُوا بِرِيحٍ صَرْصَرٍ عَاتِيَةٍ﴾ الحاقة: ٦'},
  {n:'صالح',e:'Saleh',ico:'🐪',s:'نبي ثمود',story:`صالح عليه السلام أُرسل إلى ثمود قومًا يسكنون الحجر، وكانوا ينحتون من الجبال بيوتًا فارهين، وأوتوا قوة وازدهارًا. دعاهم صالح إلى التوحيد، فطلبوا منه آية، فأخرج الله لهم ناقة من الصخرة آية بيّنة، وقال: هذه ناقة الله لكم آية، فذروها تأكل في أرض الله ولا تمسوها بسوء فيأخذكم عذاب قريب.

آمن به ضعفاؤهم، واستكبر الملأ. تآمر تسعة رهط على عقر الناقة، فعقروها وعتوا عن أمر ربهم. قال لهم صالح: تمتعوا في داركم ثلاثة أيام، ذلك وعد غير مكذوب. فلما جاء الموعد أخذتهم الرجفة والصيحة فأصبحوا في ديارهم جاثمين، كأن لم يغنوا فيها. ونجّى الله صالحًا والذين آمنوا معه.`,quran:'﴿وَإِلَىٰ ثَمُودَ أَخَاهُمْ صَالِحًا ۚ قَالَ يَا قَوْمِ اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُ﴾ الأعراف: ٧٣'},
  {n:'إبراهيم',e:'Ibrahim',ico:'🔥',s:'خليل الرحمن',story:`إبراهيم عليه السلام أبو الأنبياء وخليل الله، من أولي العزم. نشأ في قوم يعبدون الأصنام والكواكب، فأنكر عليهم، ونظر في ملكوت السماوات والأرض. حاجّ أباه آزر وقومه: أتعبدون ما تنحتون؟ وكسر أصنامهم إلا كبيرًا لهم لعلهم إليه يرجعون. فلما رأوا ما حدث همّوا بإحراقه، فبنوا بنيانًا وألقوه في النار، فقال الله: يا نار كوني بردًا وسلامًا على إبراهيم، فنجاه الله.

هاجر إلى الشام ثم إلى مصر، ثم أسكن هاجر وإسماعيل بوادٍ غير ذي زرع عند البيت المحرم. رُزق إسماعيل ثم إسحاق. ابتلاه الله بذبح إسماعيل في الرؤيا، فهمّ بتنفيذ الأمر ففداه الله بذبح عظيم. بنى مع إسماعيل قواعد البيت الحرام، ورفع قواعده، ودعوا: ربنا تقبل منا إنك أنت السميع العليم. دعا أن يبعث في ذريتهم رسولًا منهم يتلو عليهم آياتك، فكانت البشارة بمحمد ﷺ. جعل الله في ذريته النبوة والكتاب، ووصفه بأنه كان أمة قانتًا لله حنيفًا ولم يك من المشركين.`,quran:'﴿إِنَّ إِبْرَاهِيمَ كَانَ أُمَّةً قَانِتًا لِّلَّهِ حَنِيفًا وَلَمْ يَكُ مِنَ الْمُشْرِكِينَ﴾ النحل: ١٢٠'},
  {n:'لوط',e:'Lot',ico:'🌆',s:'نبي سدوم',story:`لوط عليه السلام ابن أخي إبراهيم، آمن به وهاجر معه، ثم أُرسل إلى أهل سدوم وعمورة الذين أتوا الفاحشة ما سبقهم بها من أحد من العالمين: كانوا يأتون الرجال شهوة من دون النساء. دعاهم لوط إلى تقوى الله وترك المنكر، فقالوا: أخرجوا آل لوط من قريتكم إنهم أناس يتطهرون.

جاءته الملائكة في صورة ضيف، فراودوه عن ضيفه فضيّق بهم ذرعًا. قالت الملائكة: يا لوط إنا رسل ربك لن يصلوا إليك، فأسرِ بأهلك بقطع من الليل ولا يلتفت منكم أحد إلا امرأتك. فلما جاء أمر الله جعلنا عاليها سافلها وأمطرنا عليها حجارة من سجيل منضود. نجّى الله لوطًا وأهله إلا امرأته كانت من الغابرين.`,quran:'﴿وَلُوطًا آتَيْنَاهُ حُكْمًا وَعِلْمًا وَنَجَّيْنَاهُ مِنَ الْقَرْيَةِ الَّتِي كَانَت تَّعْمَلُ الْخَبَائِثَ﴾ الأنبياء: ٧٤'},
  {n:'إسماعيل',e:'Ismail',ico:'🕋',s:'الذبيح الصادق',story:`إسماعيل عليه السلام ابن إبراهيم البكر من هاجر. أسكنهما إبراهيم عند البيت الحرام بوادٍ غير ذي زرع. لما نفد الماء سعت هاجر بين الصفا والمروة سعيًا، ففجّر الله زمزم تحت قدم إسماعيل. شبّ إسماعيل صادق الوعد وكان رسولًا نبيًّا، وكان يأمر أهله بالصلاة والزكاة.

رأى إبراهيم في المنام أنه يذبحه، فقال: يا بني إني أرى في المنام أني أذبحك فانظر ماذا ترى. قال: يا أبت افعل ما تؤمر، ستجدني إن شاء الله من الصابرين. فلما أسلما وتلّه للجبين ناداه الله أن يا إبراهيم قد صدّقت الرؤيا، وفديناه بذبح عظيم. شارك أباه في بناء الكعبة، ودعا معه أن يتقبل منهما وأن يبعث في الأمة رسولًا. هو جد العرب المستعربة وجد النبي محمد ﷺ من جهة النسب.`,quran:'﴿وَاذْكُرْ فِي الْكِتَابِ إِسْمَاعِيلَ ۚ إِنَّهُ كَانَ صَادِقَ الْوَعْدِ وَكَانَ رَسُولًا نَّبِيًّا﴾ مريم: ٥٤'},
  {n:'إسحاق',e:'Ishaq',ico:'🏡',s:'أبو يعقوب',story:`إسحاق عليه السلام ابن إبراهيم من سارة، بُشّر به بعد إسماعيل على الكبر. جاءت الملائكة بالبشرى سارة فضحكت، قالوا: أتعجبين من أمر الله؟ رحمة الله وبركاته عليكم أهل البيت. وُلد إسحاق وبُشّر من ورائه بيعقوب.

كان نبيًّا صالحًا على ملة أبيه إبراهيم، وبارك الله فيه وفي ذريته. تزوج ووُلد له عيسو ويعقوب. استمرت النبوة في نسله في بني إسرائيل، حتى خُتمت في فرع بني إسرائيل بعيسى عليه السلام، وخُتمت النبوة عامة بمحمد ﷺ من نسل إسماعيل. ذُكر إسحاق في القرآن مع إبراهيم ويعقوب في مواضع التبجيل والبركة.`,quran:'﴿وَبَشَّرْنَاهُ بِإِسْحَاقَ نَبِيًّا مِّنَ الصَّالِحِينَ﴾ الصافات: ١١٢'},
  {n:'يعقوب',e:'Yaqub',ico:'👨‍👦',s:'إسرائيل',story:`يعقوب عليه السلام هو إسرائيل، ابن إسحاق، أبو يوسف والأسباط. كان نبيًّا صابرًا حليمًا. أحب ابنه يوسف حبًّا شديدًا، فحسده إخوته وألقوه في الجبّ، ثم جاءوا بقميصه بدم كذب. قال يعقوب: بل سوّلت لكم أنفسكم أمرًا، فصبر جميل، والله المستعان على ما تصفون.

فقد بصره من الحزن على يوسف، وظل يذكره حتى قالوا: تالله تفتأ تذكر يوسف حتى تكون حرضًا أو تكون من الهالكين. قال: إنما أشكو بثي وحزني إلى الله. لما جاء البشير ألقى القميص على وجهه فارتد بصيرًا. رحل إلى مصر والتقى يوسف وعفا الله عن الجميع. أوصى بنيه عند موته: يا بني إن الله اصطفى لكم الدين فلا تموتن إلا وأنتم مسلمون.`,quran:'﴿وَوَصَّىٰ بِهَا إِبْرَاهِيمُ بَنِيهِ وَيَعْقُوبُ يَا بَنِيَّ إِنَّ اللَّهَ اصْطَفَىٰ لَكُمُ الدِّينَ﴾ البقرة: ١٣٢'},
  {n:'يوسف',e:'Yusuf',ico:'👑',s:'الصديق',story:`يوسف عليه السلام ابن يعقوب، قصته من أحسن القصص. رأى إحدى عشر كوكبًا والشمس والقمر له ساجدين. حسده إخوته فألقوه في غيابة الجبّ، والتقطه سيارة فباعوه في مصر بثمن بخس. اشتراه العزيز، وراودته امرأة العزيز عن نفسه فاستعصم، قال: معاذ الله. وُجد قميصه قُد من دبر فشهد شاهد من أهلها، ثم سُجن رغم براءته.

في السجن فسّر رؤيا صاحبيه، ثم فسّر رؤيا الملك: سبع بقرات سمان يأكلهن سبع عجاف. فأُخرج من السجن وصار على خزائن الأرض. جاءت سنو القحط فحضر إخوته يمتارون، عرفهم وهم له منكرون. دبّر أن يأخذ أخاه بنيامين، ثم عرّف نفسه: أنا يوسف وهذا أخي. أرسل قميصه إلى أبيه فارتد بصيرًا، ورفع أبويه على العرش وخرّوا له سجدًا، وقال: يا أبت هذا تأويل رؤياي من قبل. عفا عن إخوته: لا تثريب عليكم اليوم يغفر الله لكم.`,quran:'﴿قَالَ لَا تَثْرِيبَ عَلَيْكُمُ الْيَوْمَ ۖ يَغْفِرُ اللَّهُ لَكُمْ ۖ وَهُوَ أَرْحَمُ الرَّاحِمِينَ﴾ يوسف: ٩٢'},
  {n:'أيوب',e:'Ayyub',ico:'💪',s:'الصابر',story:`أيوب عليه السلام نبي من أنبياء الله الصابرين. آتاه الله أهلًا ومالًا ثم ابتُلي في جسده وماله وأهله بلاءً شديدًا طويلًا، فصبر صبرًا جميلًا ولم يجزع ولم يكفر. بقي يذكر الله ويحمده، حتى ضرب به المثل في الصبر.

نادى ربه: أني مسني الضر وأنت أرحم الراحمين. فاستجاب الله له فكشف ما به من ضر، وآتاه أهله ومثلهم معهم رحمة من عنده وذكرى للعابدين. قيل له: اركض برجلك هذا مغتسل بارد وشراب. وأُمر أن يأخذ بيده ضغثًا فيضرب به ولا يحنث. جعله الله أسوة للصابرين في البلاء.`,quran:'﴿وَأَيُّوبَ إِذْ نَادَىٰ رَبَّهُ أَنِّي مَسَّنِيَ الضُّرُّ وَأَنتَ أَرْحَمُ الرَّاحِمِينَ﴾ الأنبياء: ٨٣'},
  {n:'شعيب',e:'Shuaib',ico:'⚖️',s:'خطيب الأنبياء',story:`شعيب عليه السلام أُرسل إلى مدين وإلى أصحاب الأيكة. كان فصيحًا بليغًا حتى سُمّي خطيب الأنبياء. دعا قومه إلى عبادة الله وحده، ونهاهم عن التطفيف في الميزان والمكيال وأكل أموال الناس بالباطل: أوفوا الكيل ولا تكونوا من المخسرين، وزنوا بالقسطاس المستقيم.

كذبوه وقالوا: يا شعيب أصلاتك تأمرك أن نترك ما يعبد آباؤنا أو أن نفعل في أموالنا ما نشاء؟ هددوه بالإخراج. فأخذتهم الرجفة فأصبحوا في ديارهم جاثمين، ونجّى الله شعيبًا والذين آمنوا معه. قصته عبرة في العدل التجاري والتوحيد.`,quran:'﴿وَإِلَىٰ مَدْيَنَ أَخَاهُمْ شُعَيْبًا قَالَ يَا قَوْمِ اعْبُدُوا اللَّهَ وَأَوْفُوا الْمِكْيَالَ وَالْمِيزَانَ﴾ هود: ٨٤'},
  {n:'موسى',e:'Musa',ico:'🌊',s:'كليم الله',story:`موسى عليه السلام من أولي العزم ومن أكثر الأنبياء ذكرًا في القرآن. وُلد في زمن فرعون الذي كان يذبّح أبناء بني إسرائيل. ألقته أمه في اليم فألقاه اليم بساحل آل فرعون، فالتقطه آل فرعون وحرّم الله عليه المراضع حتى رُدّ إلى أمه. شبّ في قصر فرعون، ثم قتل قبطيًّا خطأً فخرج إلى مدين خائفًا.

في مدين سقى للبنتين، وتزوج ابنة شعيب، وقضى أجلًا. ناداه الله من جانب الطور الأيمن في الوادي المقدس طوى: يا موسى إني أنا الله. أمره أن يذهب إلى فرعون إنه طغى، وشدّ أزره بأخيه هارون. ألقى عصاه فإذا هي ثعبان مبين، ونزع يده فإذا هي بيضاء للناظرين. تحدّى السحرة فآمنوا، ونجّى الله بني إسرائيل وشقّ لهم البحر فأغرق فرعون وجنوده.

آتى الله موسى التوراة فيها هدى ونور. صام أربعين ليلة، وعبد قومه العجل في غيبته فغضب وأخذ برأس أخيه. دعا لقومه بالمن والسلوى، وضرب الحجر فانفجرت منه اثنتا عشرة عينًا. رفض بنو إسرائيل دخول الأرض المقدسة فضُربت عليهم التيه أربعين سنة.`,quran:'﴿وَكَلَّمَ اللَّهُ مُوسَىٰ تَكْلِيمًا﴾ النساء: ١٦٤'},
  {n:'هارون',e:'Harun',ico:'🗣️',s:'وزير موسى',story:`هارون عليه السلام أخو موسى وأفصح منه لسانًا. طلب موسى من ربه أن يرسله معه ردءًا يصدّقه، فآتاه الله سؤله وجعله شريكًا في الأمر. كان وزيرًا لموسى وعضدًا له في الدعوة أمام فرعون وملئه.

لما ذهب موسى إلى الميقات واستخلف هارون على قومه، اتخذ السامري لهم عجلًا جسدًا له خوار فعبدوه. نهاهم هارون فلم يطيعوه، وكادوا يقتلونه. رجع موسى غاضبًا فأخذ برأس أخيه يجرّه إليه، فقال هارون: يا ابن أم لا تأخذ بلحيتي ولا برأسي، إني خشيت أن تقول فرّقت بين بني إسرائيل. بيّن موسى براءة هارون، وأحرق العجل ونسفه في اليم نسفًا.`,quran:'﴿وَأَخِي هَارُونُ هُوَ أَفْصَحُ مِنِّي لِسَانًا فَأَرْسِلْهُ مَعِيَ رِدْءًا﴾ القصص: ٣٤'},
  {n:'ذو الكفل',e:'Dhul-Kifl',ico:'📿',s:'الصابر الكافل',story:`ذو الكفل عليه السلام نبي من أنبياء بني إسرائيل، ذكره الله في الأنبياء وص ووصفه بالصبر والصلاح. قيل سُمّي بذلك لأنه تكفّل بأمور قومه وقضى بينهم بالعدل، أو لأنه كفل نفسه بالعمل الصالح والقيام بالحق.

عدّه الله مع الصابرين الأخيار: إسماعيل وإدريس وذا الكفل، كل من الصابرين. وأُدخل في رحمة الله إنه من الصالحين. قصته تذكّر بأن النبوة والصلاح مقترنان بالصبر والوفاء بالعهد والعدل بين الناس.`,quran:'﴿وَإِسْمَاعِيلَ وَإِدْرِيسَ وَذَا الْكِفْلِ ۖ كُلٌّ مِّنَ الصَّابِرِينَ﴾ الأنبياء: ٨٥'},
  {n:'داود',e:'Dawud',ico:'⚔️',s:'النبي الملك',story:`داود عليه السلام نبي وملك لبني إسرائيل. قتل جالوت وكان ذلك بداية ملكه. آتاه الله الملك والحكمة وفصل الخطاب، وسخّر له الجبال يسبّحن معه والطير، وألان له الحديد. كان يصوم يومًا ويفطر يومًا، وكان يقوم الليل.

أُوتي الزبور، وكان حسن الصوت بتلاوته حتى كانت الجبال والطير ترجع معه. حكم بين الناس بالعدل. ابتُلي في قصة الحرث والغنم وحكم فيها مع سليمان، ففهمها سليمان. تاب إلى الله وخرّ راكعًا وأناب. جعله الله خليفة في الأرض ليحكم بين الناس بالحق.`,quran:'﴿يَا دَاوُودُ إِنَّا جَعَلْنَاكَ خَلِيفَةً فِي الْأَرْضِ فَاحْكُم بَيْنَ النَّاسِ بِالْحَقِّ﴾ ص: ٢٦'},
  {n:'سليمان',e:'Sulaiman',ico:'🧞',s:'نبي الحكمة',story:`سليمان عليه السلام ابن داود، ورثه علمًا وملكًا. علّمه الله منطق الطير وسخّر له الجن والريح تجري بأمره رخاءً حيث أصاب. فهم حديث النملة فتبسم ضاحكًا من قولها. تفقد الطير ففقد الهدهد فجاءه بخبر سبأ وملكتها التي يعبدون الشمس من دون الله.

أرسل إلى بلقيس كتابًا كريمًا: ألا تعلوا عليّ وأتوني مسلمين. جاءت مسلمة بعد أن رأى عرشه منقولًا، وقالت: رب إني ظلمت نفسي وأسلمت مع سليمان لله رب العالمين. كان سليمان شاكرًا لأنعم الله، وسأل ربًا ملكًا لا ينبغي لأحد من بعده. مات قائمًا على عصاه ولم تعلم الجن موته إلا حين أكلت دابة الأرض منسأته فخرّ.`,quran:'﴿وَوُرِثَ سُلَيْمَانُ دَاوُودَ ۖ وَقَالَ يَا أَيُّهَا النَّاسُ عُلِّمْنَا مَنطِقَ الطَّيْرِ﴾ النمل: ١٦'},
  {n:'إلياس',e:'Elias',ico:'⚡',s:'نبي بني إسرائيل',story:`إلياس عليه السلام من أنبياء بني إسرائيل، دعا قومه إلى عبادة الله وترك عبادة بعل. قال: أتدعون بعلًا وتذرون أحسن الخالقين؟ الله ربكم ورب آبائكم الأولين. فكذبوه فأوعدهم.

سلام على إل ياسين، كذلك نجزي المحسنين، إنه من عبادنا المؤمنين. جعله الله مع المصطفين الأخيار. رسالته تذكير بنبذ الشرك وعبادة الله وحده في زمن كثرت فيه الانحرافات عند بني إسرائيل.`,quran:'﴿وَإِنَّ إِلْيَاسَ لَمِنَ الْمُرْسَلِينَ ۝ إِذْ قَالَ لِقَوْمِهِ أَلَا تَتَّقُونَ﴾ الصافات: ١٢٣–١٢٤'},
  {n:'اليسع',e:'Elisha',ico:'🕊️',s:'نبي بني إسرائيل',story:`اليسع عليه السلام من أنبياء بني إسرائيل المصطفين الأخيار. ذُكر في القرآن مع إسماعيل ويونس ولوط، وكلًّا فضّل الله على العالمين. سار على نهج الأنبياء في الدعوة إلى التوحيد وإصلاح بني إسرائيل.

كان امتدادًا لرسالة إلياس في قومه، يدعو للحق والصبر على الطاعة. ذكره في القرآن يبيّن سلسلة النبوة المتصلة في بني إسرائيل قبل زكريا ويحيى وعيسى.`,quran:'﴿وَإِسْمَاعِيلَ وَالْيَسَعَ وَيُونُسَ وَلُوطًا ۚ وَكُلًّا فَضَّلْنَا عَلَى الْعَالَمِينَ﴾ الأنعام: ٨٦'},
  {n:'يونس',e:'Yunus',ico:'🐋',s:'ذو النون',story:`يونس عليه السلام ذو النون، أُرسل إلى قوم نينوى فدعاهم فكذبوه. خرج مغاضبًا قبل أن يأذن الله، وظن أن لن نقدر عليه. ركب البحر فاقتسموا فكانت القرعة عليه، فأُلقي في اليم فالتقمه الحوت وهو مليم.

نادى في الظلمات: أن لا إله إلا أنت سبحانك إني كنت من الظالمين. فاستجاب الله له ونجّاه من الغم، وكذلك ننجي المؤمنين. نبذه الحوت بالعراء وهو سقيم، وأنبت الله عليه شجرة من يقطين. أرسله الله إلى مئة ألف أو يزيدون فآمنوا فمتعهم الله إلى حين. وهو النبي الذي آمن قومه جميعًا بعد أن كاد العذاب يقع بهم.`,quran:'﴿فَنَادَىٰ فِي الظُّلُمَاتِ أَن لَّا إِلَٰهَ إِلَّا أَنتَ سُبْحَانَكَ إِنِّي كُنتُ مِنَ الظَّالِمِينَ﴾ الأنبياء: ٨٧'},
  {n:'زكريا',e:'Zakariya',ico:'🛕',s:'كافل مريم',story:`زكريا عليه السلام من أنبياء بني إسرائيل، كفل مريم بنت عمران لما نذرتها أمها للمحرّر. كلما دخل عليها المحراب وجد عندها رزقًا، قال: يا مريم أنّى لك هذا؟ قالت: هو من عند الله.

دعا ربه نداءً خفيًّا: رب إني وهن العظم مني واشتعل الرأس شيبًا... هب لي من لدنك ذرية طيبة. فنادته الملائكة وهو قائم يصلي في المحراب أن الله يبشرك بيحيى. قال: رب أنّى يكون لي غلام وقد بلغني الكبر وامرأتي عاقر؟ قال: كذلك الله يفعل ما يشاء. آيته ألا يكلم الناس ثلاث ليالٍ سويًّا. رُزق يحيى على الكبر، وكان ذلك آية من الله.`,quran:'﴿هُنَالِكَ دَعَا زَكَرِيَّا رَبَّهُ ۖ قَالَ رَبِّ هَبْ لِي مِن لَّدُنكَ ذُرِّيَّةً طَيِّبَةً﴾ آل عمران: ٣٨'},
  {n:'يحيى',e:'Yahya',ico:'🌿',s:'الحصور',story:`يحيى عليه السلام ابن زكريا، وهبه الله على الكبر بعد بشارة الملائكة. آتاه الله الحكم صبيًّا، وحنانًا من لدنه وزكاة، وكان تقيًّا وبرًّا بوالديه ولم يكن جبارًا عصيا. سُمّي يحيى ولم يجعل الله له من قبل سميًّا.

أخذ الكتاب بقوة، وكان حصورًا صدّيقًا نبيًّا من الصالحين. بشّر بعيسى وصدّقه. دعا بني إسرائيل إلى التوبة والإصلاح. قُتل ظلمًا، ورفع الله مكانته. سلام عليه يوم وُلد ويوم يموت ويوم يُبعث حيًّا.`,quran:'﴿يَا يَحْيَىٰ خُذِ الْكِتَابَ بِقُوَّةٍ ۖ وَآتَيْنَاهُ الْحُكْمَ صَبِيًّا﴾ مريم: ١٢'},
  {n:'عيسى',e:'Isa',ico:'✨',s:'المسيح',story:`عيسى عليه السلام المسيح ابن مريم، من أولي العزم. وُلد بمعجزة من غير أب، إذ قالت مريم: أنّى يكون لي غلام ولم يمسسني بشر؟ قال: كذلك الله يخلق ما يشاء. تكلم في المهد صبيًّا: إني عبد الله آتاني الكتاب وجعلني نبيًّا.

أُوتي الإنجيل، وأُيد بروح القدس. كان يخلق من الطين كهيئة الطير فينفخ فيه فيكون طيرًا بإذن الله، ويبرئ الأكمه والأبرص ويحيي الموتى بإذن الله، وينبئهم بما يأكلون وما يدّخرون في بيوتهم. دعا بني إسرائيل إلى عبادة الله ربه وربهم.

لما كفروا همّوا بقتله، قال الله: إني متوفيك ورافعك إليّ ومطهرك من الذين كفروا. شبّه لهم فلم يقتلوه ولم يصلبوه ولكن شُبّه لهم. هو عبد الله ورسوله وكلمته ألقاها إلى مريم وروح منه. ينزل آخر الزمان فيكسر الصليب ويقتل الخنزير ويحكم بالإسلام.`,quran:'﴿إِنَّمَا الْمَسِيحُ عِيسَى ابْنُ مَرْيَمَ رَسُولُ اللَّهِ وَكَلِمَتُهُ أَلْقَاهَا إِلَىٰ مَرْيَمَ وَرُوحٌ مِّنْهُ﴾ النساء: ١٧١'},
  {n:'محمد',e:'Muhammad',ico:'🌙',s:'خاتم النبيين',story:`محمد ﷺ خاتم الأنبياء والمرسلين، أرسله الله رحمة للعالمين إلى الناس كافة. وُلد بمكة يتيمًا، ونشأ على الصدق والأمانة حتى لُقّب بالصادق الأمين. تزوّج خديجة، وفي غار حراء جاءه جبريل بالوحي: اقرأ باسم ربك الذي خلق.

دعا إلى التوحيد سرًّا ثم جهرًا، فصبر على الأذى والسخرية والحصار. أُسري به من المسجد الحرام إلى المسجد الأقصى وعُرج به إلى السماء. بايع الأنصار وهاجر إلى المدينة، فآخى بين المهاجرين والأنصار، وأسس دولة الإسلام، وكتب الوثائق، وغزا دفاعًا عن الدين حتى فتح مكة فقال: اذهبوا فأنتم الطلقاء.

نزل عليه القرآن وهو المعجزة الخالدة، وأكمل الله له الدين وأتم النعمة. بلّغ الرسالة وأدّى الأمانة ونصح الأمة. توفي في المدينة وله من العمر ثلاث وستون سنة، وترك القرآن والسنة. هو سيد ولد آدم، وصاحب الشفاعة والمقام المحمود، ولا نبي بعده.`,quran:'﴿مَّا كَانَ مُحَمَّدٌ أَبَا أَحَدٍ مِّن رِّجَالِكُمْ وَلَٰكِن رَّسُولَ اللَّهِ وَخَاتَمَ النَّبِيِّينَ﴾ الأحزاب: ٤٠'}
]

var _selectedProphet=null;
function buildProphets2(){
  var grid=document.getElementById('prophets2-grid');
  if(!grid||grid.children.length)return;
  PROPHETS2.forEach(function(p,i){
    var card=document.createElement('div');
    card.style.cssText='background:rgba(13,59,46,.5);border:1px solid rgba(201,168,76,.18);border-radius:14px;padding:.9rem;cursor:pointer;transition:all .2s;text-align:center;';
    card.innerHTML='<div style="font-size:1.8rem;margin-bottom:.3rem;">'+p.ico+'</div>'
      +'<div style="font-family:\'Scheherazade New\',serif;font-size:1rem;color:#f0d080;">'+p.n+'</div>'
      +'<div style="font-size:.72rem;color:var(--tm);margin-top:.2rem;">'+p.s+'</div>';
    card.onclick=function(){ showProphetDetail(i); };
    grid.appendChild(card);
  });
}

function showProphetDetail(idx){
  var p=PROPHETS2[idx];
  var det=document.getElementById('prophets2-detail');
  var grid=document.getElementById('prophets2-grid');
  if(!det||!p)return;
  det.style.display='block';
  if(grid)grid.style.display='none';
  det.innerHTML='<button onclick="hideProphetDetail()" style="background:rgba(201,168,76,.08);border:1px solid rgba(201,168,76,.2);color:var(--tm);padding:.4rem .8rem;border-radius:8px;font-family:Tajawal,sans-serif;font-size:.8rem;cursor:pointer;margin-bottom:1rem;">← العودة للقائمة</button>'
    +'<div style="background:linear-gradient(135deg,rgba(13,59,46,.8),rgba(3,10,6,.9));border:1px solid rgba(201,168,76,.3);border-radius:18px;padding:1.3rem;">'
    +'<div style="text-align:center;margin-bottom:1rem;">'
    +'<div style="font-size:3rem;margin-bottom:.3rem;">'+p.ico+'</div>'
    +'<div style="font-family:\'Scheherazade New\',serif;font-size:1.8rem;color:#f0d080;">'+p.n+'</div>'
    +'<div style="font-size:.78rem;color:var(--gold);margin-top:.2rem;">'+p.s+' — '+p.e+'</div>'
    +'</div>'
    +'<div style="font-size:.92rem;color:var(--cr);line-height:2.1;margin-bottom:1rem;text-align:right;white-space:pre-line;">'+p.story+'</div>'
    +'<div style="background:rgba(201,168,76,.08);border:1px solid rgba(201,168,76,.2);border-radius:12px;padding:.8rem;text-align:center;">'
    +'<div style="font-size:.7rem;color:var(--tm);margin-bottom:.3rem;">آية قرآنية</div>'
    +'<div style="font-family:\'Scheherazade New\',serif;font-size:1rem;color:#f0d080;line-height:2;">'+p.quran+'</div>'
    +'</div>'
    +'<div style="display:flex;justify-content:center;gap:.5rem;margin-top:.8rem;">'
    +(idx>0?'<button onclick="showProphetDetail('+(idx-1)+')" style="background:rgba(201,168,76,.08);border:1px solid rgba(201,168,76,.2);color:var(--gold);padding:.4rem .9rem;border-radius:8px;font-family:Tajawal,sans-serif;font-size:.82rem;cursor:pointer;">→ '+PROPHETS2[idx-1].n+'</button>':'')
    +(idx<PROPHETS2.length-1?'<button onclick="showProphetDetail('+(idx+1)+')" style="background:rgba(201,168,76,.08);border:1px solid rgba(201,168,76,.2);color:var(--gold);padding:.4rem .9rem;border-radius:8px;font-family:Tajawal,sans-serif;font-size:.82rem;cursor:pointer;">'+PROPHETS2[idx+1].n+' ←</button>':'')
    +'</div>'
    +'</div>';
}
function hideProphetDetail(){
  var det=document.getElementById('prophets2-detail');
  var grid=document.getElementById('prophets2-grid');
  if(det)det.style.display='none';
  if(grid)grid.style.display='grid';
}

