var _fiqhCat='الطهارة';
function buildFiqh(){
  var catsEl=document.getElementById('fiqh-cats');
  if(!catsEl||catsEl.children.length)return;
  Object.keys(FIQH_DATA).forEach(function(cat){
    var icons={'الطهارة':'💧','الصلاة':'🕌','الصيام':'🌙','الزكاة':'💰','الحج':'🕋'};
    var btn=document.createElement('button');
    btn.textContent=(icons[cat]||'📋')+' '+cat;
    btn.dataset.cat=cat;
    btn.style.cssText='background:rgba(201,168,76,'+(cat===_fiqhCat?'.2':'.07')+');border:1px solid rgba(201,168,76,'+(cat===_fiqhCat?'.5':'.2')+');color:'+(cat===_fiqhCat?'#f0d080':'var(--tm)')+';padding:.5rem 1rem;border-radius:50px;font-family:Tajawal,sans-serif;font-size:.85rem;cursor:pointer;transition:all .2s;';
    btn.onclick=function(){
      _fiqhCat=cat;
      catsEl.querySelectorAll('button').forEach(function(b){
        var a=b.dataset.cat===cat;
        b.style.background=a?'rgba(201,168,76,.2)':'rgba(201,168,76,.07)';
        b.style.borderColor=a?'rgba(201,168,76,.5)':'rgba(201,168,76,.2)';
        b.style.color=a?'#f0d080':'var(--tm)';
      });
      renderFiqh();
    };
    catsEl.appendChild(btn);
  });
  renderFiqh();
}

function renderFiqh(){
  var box=document.getElementById('fiqh-content');
  if(!box)return;
  var items=FIQH_DATA[_fiqhCat]||[];
  var html='';
  items.forEach(function(item){
    html+='<div style="background:rgba(13,59,46,.4);border:1px solid rgba(201,168,76,.15);border-radius:14px;padding:1rem 1.1rem;margin-bottom:.7rem;">'
      +'<div style="color:#f0d080;font-weight:700;font-size:.92rem;margin-bottom:.5rem;">📌 '+item.t+'</div>'
      +'<div style="font-size:.85rem;color:var(--tm);line-height:1.95;direction:rtl;">'+item.c+'</div>'
      +'</div>';
  });
  box.innerHTML=html;
}

