var THEMES=[
  {id:'paper',   name:'ورقي',  cls:'theme-paper'},
  {id:'emerald', name:'زمردي', cls:''}
];
var _currentTheme=(function(){ var t=localStorage.getItem('nq_theme'); return (t==='paper'||t==='emerald')?t:'paper'; })(); // الافتراضي ورقي، وأي ثيم قديم يُهاجَر إليه
var _fontSize=parseInt(localStorage.getItem('nq_fontsize'))||18;

function applyTheme(id){
  if(id!=='paper'&&id!=='emerald') id='paper';
  _currentTheme=id;
  try{localStorage.setItem('nq_theme',id);}catch(e){}
  document.body.classList.toggle('theme-paper', id==='paper');
  var m=document.querySelector('meta[name="theme-color"]'); if(m) m.setAttribute('content', id==='paper'?'#E9E1CC':'#030A06');
  document.querySelectorAll('[data-mode-lbl]').forEach(function(l){ l.textContent = id==='paper' ? 'الوضع الزمردي' : 'الوضع الورقي'; });
  document.querySelectorAll('[data-mode-btn]').forEach(function(b){ b.setAttribute('aria-pressed', id==='emerald'); });
}
function toggleMode(){ applyTheme(_currentTheme==='paper'?'emerald':'paper'); }
function renderThemesGrid(){}
function buildThemes(){ applyFontSize(_fontSize); }

function applyFontSize(sz){
  _fontSize = Math.max(12, Math.min(32, sz));
  localStorage.setItem('nq_fontsize', _fontSize);
  // آيات قرآنية وأذكار
  document.querySelectorAll('.vbv-text,.ayah-text,.quran-text,.zikr-ar,.wird-arabic,.ai-quran').forEach(function(el){
    el.style.fontSize = Math.round(_fontSize * 1.5) + 'px';
  });
  // نص عام في كل الموقع
  document.querySelectorAll('.ai-bubble-bot,.ai-body,.hadith-text,.quiz-q,.pg p:not(.ai-bubble-bot p),.wird-card p').forEach(function(el){
    el.style.fontSize = _fontSize + 'px';
  });
  // حجم الخط الأساسي على body
  document.body.style.fontSize = _fontSize + 'px';
  // شريط التحكم
  var bar = document.getElementById('font-bar');
  var lbl = document.getElementById('font-size-lbl');
  var prev = document.getElementById('font-preview');
  var prevUI = document.getElementById('font-preview-ui');
  var pct = Math.round(((_fontSize - 12) / 20) * 100);
  if(bar) bar.style.width = pct + '%';
  if(lbl) lbl.textContent = _fontSize + 'px';
  if(prev) prev.style.fontSize = Math.round(_fontSize * 1.4) + 'px';
  if(prevUI) prevUI.style.fontSize = _fontSize + 'px';
}
function changeFontSize(delta){ applyFontSize(_fontSize + delta); }
function confirmFontSize(){ localStorage.setItem('nq_fontsize',_fontSize); var b=document.getElementById('font-confirm-btn');if(b){b.textContent='✅ تم الحفظ';setTimeout(function(){b.textContent='✔ تأكيد';},1500);} }
function resetFontSize(){ applyFontSize(18); }

// Apply saved theme on load
(function(){ applyTheme(_currentTheme); applyFontSize(_fontSize); })();

// ══════════════════════════════════════════════════
// 📊 STATS — Fixed version
// ══════════════════════════════════════════════════
function getStats(){
  try{ return JSON.parse(localStorage.getItem('nq_stats')||'{}'); }
  catch(e){ return {}; }
}
function saveStats(s){ try{ localStorage.setItem('nq_stats',JSON.stringify(s)); }catch(e){} }

function trackAction(key){
  var s=getStats();
  s[key]=(s[key]||0)+1;
  // track streak
  var today=new Date().toDateString();
  if(!s.days) s.days={};
  if(!s.days[today]) s.days[today]={};
  s.days[today][key]=(s.days[today][key]||0)+1;
  // total sessions
  s.sessions=(s.sessions||0)+1;
  saveStats(s);
}

// Track time spent
var _pageOpenTime=Date.now();
window.addEventListener('visibilitychange',function(){
  if(document.hidden){
    var s=getStats();
    s.minutes=(s.minutes||0)+Math.round((Date.now()-_pageOpenTime)/60000);
    saveStats(s);
  } else {
    _pageOpenTime=Date.now();
  }
});

// Hook SP for tracking - replace existing hook
var _origSP2=window.SP;
window.SP=function(id,ph){
  if(id==='quran'||id==='tafsir'||id==='hifz'||id==='tajweed'||id==='qsearch'||id==='reciters') trackAction('quran_visits');
  if(id==='prayer'||id==='adhan') trackAction('prayer_checks');
  if(id==='wird'||id==='hisn'||id==='asma') trackAction('dikr_visits');
  if(id==='hadiths') trackAction('hadith_visits');
  if(id==='seerah'||id==='prophets'||id==='prophets2') trackAction('seerah_visits');
  if(id==='quiz') trackAction('quiz_visits');
  trackAction('page_'+id);
  if(_origSP2) _origSP2(id,ph);
};

function objTotal(obj){
  var t=0;
  for(var k in obj){ if(obj.hasOwnProperty(k)) t+=obj[k]; }
  return t;
}

function buildStats(){
  var s=getStats();
  var grid=document.getElementById('stats-grid');
  var week=document.getElementById('stats-week');
  var ach=document.getElementById('stats-achievements');
  if(!grid)return;

  // Count total pages visited
  var totalPages=0;
  for(var k in s){ if(k.indexOf('page_')===0) totalPages+=s[k]; }

  var items=[
    {n:s.quran_visits||0,  l:'جلسة تلاوة',    ico:'📖', color:'#5BA3D9'},
    {n:s.dikr_visits||0,   l:'جلسة ذكر',      ico:'📿', color:'#2DD4A4'},
    {n:s.hadith_visits||0, l:'زيارة الأحاديث', ico:'📜', color:'#F0C040'},
    {n:s.prayer_checks||0, l:'متابعة صلوات',  ico:'🕌', color:'#C9A84C'},
    {n:s.seerah_visits||0, l:'زيارة السيرة',   ico:'🌙', color:'#DDA0DD'},
    {n:s.quiz_visits||0,   l:'جلسة اختبار',   ico:'❓', color:'#FF9F7F'},
    {n:s.minutes||0,       l:'دقيقة في الموقع',ico:'⏱', color:'#7ae87a'},
    {n:totalPages||0,       l:'صفحة زُرت',     ico:'🗂', color:'#e87a7a'}
  ];

  grid.innerHTML='';
  items.forEach(function(it){
    grid.innerHTML+='<div class="stat-card" style="border-color:'+it.color+'22;">'
      +'<div style="font-size:1.5rem;">'+it.ico+'</div>'
      +'<div class="stat-num" style="color:'+it.color+';">'+it.n+'</div>'
      +'<div class="stat-lbl">'+it.l+'</div></div>';
  });

  // شريط التقدم الأسبوعي
  var days=['ح','ن','ث','ر','خ','ج','س'];
  var today=new Date();
  var wHtml='<div style="font-size:.78rem;color:var(--tm);margin-bottom:.5rem;">النشاط الأسبوعي</div>'
    +'<div style="display:flex;gap:.3rem;justify-content:space-between;">';
  for(var i=6;i>=0;i--){
    var d=new Date(today); d.setDate(d.getDate()-i);
    var dk=d.toDateString();
    var dayData=(s.days&&s.days[dk])||{};
    var total=objTotal(dayData);
    var isToday=(i===0);
    var intensity=Math.min(total,5);
    var alpha=intensity>0?(0.2+intensity*0.16):0.07;
    wHtml+='<div style="flex:1;text-align:center;">'
      +'<div style="width:100%;aspect-ratio:1;border-radius:6px;background:rgba(201,168,76,'+alpha+');'
      +'border:1px solid rgba(201,168,76,'+(intensity>0?'.4':'.12')+');'
      +(isToday?'box-shadow:0 0 6px rgba(201,168,76,.4);':'')
      +';margin:0 auto .3rem;transition:all .3s;"></div>'
      +'<div style="font-size:.6rem;color:'+(isToday?'var(--gold)':'var(--tm)')+';">'+days[d.getDay()]+'</div>'
      +'</div>';
  }
  wHtml+='</div>';
  wHtml+='<div style="margin-top:.5rem;font-size:.7rem;color:var(--tm);text-align:center;">اللون أغمق = نشاط أكثر</div>';
  if(week) week.innerHTML=wHtml;

  // الإنجازات
  var allAch=[
    {con:(s.quran_visits||0)>=1,   ico:'🌱',t:'أول خطوة',       s:'فتحت القرآن لأول مرة'},
    {con:(s.quran_visits||0)>=5,   ico:'📖',t:'قارئ منتظم',     s:'قرأت القرآن 5 مرات'},
    {con:(s.quran_visits||0)>=20,  ico:'🏆',t:'حافظ متميّز',    s:'20 جلسة تلاوة — ماشاء الله!'},
    {con:(s.dikr_visits||0)>=3,    ico:'📿',t:'لسانه رطب بالذكر',s:'زرت الأذكار 3 مرات'},
    {con:(s.dikr_visits||0)>=10,   ico:'💎',t:'مداوم على الذكر', s:'10 جلسات ذكر متواصلة'},
    {con:(s.prayer_checks||0)>=7,  ico:'🕌',t:'حارس الصلاة',    s:'تابعت صلواتك 7 أيام'},
    {con:(s.hadith_visits||0)>=5,  ico:'📜',t:'طالب حديث',      s:'قرأت الأحاديث 5 مرات'},
    {con:(s.quiz_visits||0)>=3,    ico:'🎓',t:'طالب علم',        s:'أجريت 3 اختبارات'},
    {con:(s.seerah_visits||0)>=3,  ico:'🌙',t:'مُحبّ السيرة',   s:'زرت السيرة النبوية 3 مرات'},
    {con:(s.minutes||0)>=60,       ico:'⏰',t:'ساعة كاملة',      s:'قضيت ساعة في هُدى القرآن'},
    {con:(s.minutes||0)>=300,      ico:'🌟',t:'متفانٍ في العلم', s:'5 ساعات في الموقع — بارك الله فيك!'},
    {con:totalPages>=50,            ico:'🗺',t:'مستكشف الموقع',  s:'زرت 50 صفحة مختلفة'}
  ];

  var earned=allAch.filter(function(a){return a.con;});
  var locked=allAch.filter(function(a){return !a.con;});

  var achHtml='';
  if(earned.length){
    achHtml+='<div style="font-size:.72rem;color:var(--gold);margin-bottom:.4rem;">🏅 محقّقة ('+earned.length+')</div>';
    earned.forEach(function(a){
      achHtml+='<div style="display:flex;gap:.7rem;align-items:center;padding:.55rem 0;border-bottom:1px solid rgba(201,168,76,.08);">'
        +'<span style="font-size:1.5rem;">'+a.ico+'</span>'
        +'<div><div style="font-size:.85rem;color:#f0d080;font-weight:700;">'+a.t+'</div>'
        +'<div style="font-size:.72rem;color:var(--tm);">'+a.s+'</div></div>'
        +'<span style="margin-right:auto;color:var(--gold);font-size:.8rem;">✓</span></div>';
    });
  }
  if(locked.length){
    achHtml+="<div style=\"font-size:.72rem;color:var(--tm);margin-top:.6rem;margin-bottom:.3rem;\">🔒 مقفلة ("+locked.length+")</div>";
    locked.slice(0,4).forEach(function(a){
      achHtml+='<div style="display:flex;gap:.7rem;align-items:center;padding:.45rem 0;border-bottom:1px solid rgba(201,168,76,.05);opacity:.5;">'
        +'<span style="font-size:1.3rem;filter:grayscale(1);">'+a.ico+'</span>'
        +'<div><div style="font-size:.82rem;color:var(--tm);">'+a.t+'</div>'
        +'<div style="font-size:.7rem;color:var(--tm);opacity:.7;">'+a.s+'</div></div></div>';
    });
  }
  if(!earned.length) achHtml='<div style="text-align:center;color:var(--tm);font-size:.85rem;padding:.8rem;">🌱 ابدأ باستخدام الموقع لتفتح الإنجازات!</div>';
  if(ach) ach.innerHTML=achHtml;
}

function resetStats(){
  if(confirm('هل تريد مسح كل الإحصائيات؟')){
    localStorage.removeItem('nq_stats');
    buildStats();
  }
}

// ══════════════════════════════════════════════════
// 🔍 GLOBAL SEARCH
// ══════════════════════════════════════════════════
var _gsFilter='all';
function gsToggleFilter(btn,f){
  _gsFilter=f;
  document.querySelectorAll('.gs-fbtn').forEach(function(b){
    var a=b.dataset.f===f;
    b.style.background=a?'rgba(201,168,76,.2)':'rgba(201,168,76,.07)';
    b.style.borderColor=a?'rgba(201,168,76,.4)':'rgba(201,168,76,.2)';
    b.style.color=a?'#f0d080':'var(--tm)';
  });
  doGlobalSearch();
}

function doGlobalSearch(){
  var inp=document.getElementById('gs-inp');
  var res=document.getElementById('gs-results');
  var cnt=document.getElementById('gs-count');
  if(!inp||!res)return;
  var q=(inp.value||'').trim();
  if(q.length<2){ res.innerHTML='<div style="text-align:center;color:var(--tm);padding:2rem;font-size:.85rem;">اكتب كلمتين على الأقل للبحث</div>'; if(cnt)cnt.textContent=''; return; }
  var results=[];
  var re=new RegExp(q,'g');
  function hl(txt){ return txt.replace(re,'<mark class="gs-hl">'+q+'</mark>'); }

  // بحث في أسماء السور
  if((_gsFilter==='all'||_gsFilter==='quran')&&typeof SM!=='undefined'){
    SM.forEach(function(s){
      if(s.ar.includes(q)||s.en.toLowerCase().includes(q.toLowerCase())){
        results.push({type:'quran',tag:'📖 سورة',color:'#5BA3D9',
          title:'سورة '+s.ar,sub:'السورة رقم '+s.n+' — '+s.ay+' آية',
          action:function(n){return function(){SP('quran');setTimeout(function(){if(typeof loadSurah==='function')loadSurah(n);},300);};}(s.n)});
      }
    });
  }

  // بحث في الأحاديث
  if((_gsFilter==='all'||_gsFilter==='hadith')&&typeof HADITHS!=='undefined'){
    HADITHS.forEach(function(h){
      if((h.text||'').includes(q)||(h.title||'').includes(q)){
        results.push({type:'hadith',tag:'📜 حديث',color:'#F0C040',
          title:h.title||'حديث شريف',sub:(h.text||'').slice(0,80)+'...',
          action:function(){SP('hadiths');}});
      }
    });
  }

  // بحث في الأنبياء
  if((_gsFilter==='all'||_gsFilter==='prophets')&&typeof PROPHETS2!=='undefined'){
    PROPHETS2.forEach(function(p,i){
      if(p.n.includes(q)||p.story.includes(q)||p.s.includes(q)){
        results.push({type:'prophets',tag:'👳 نبي',color:'#A8E6CF',
          title:p.ico+' '+p.n+' — '+p.s,sub:p.story.slice(0,80)+'...',
          action:function(idx){return function(){SP('prophets2');setTimeout(function(){showProphetDetail(idx);},200);};}(i)});
      }
    });
  }

  // بحث في الفقه
  if((_gsFilter==='all'||_gsFilter==='fiqh')&&typeof FIQH_DATA!=='undefined'){
    Object.keys(FIQH_DATA).forEach(function(cat){
      FIQH_DATA[cat].forEach(function(item){
        if(item.t.includes(q)||item.c.includes(q)){
          results.push({type:'fiqh',tag:'📋 فقه',color:'#DDA0DD',
            title:item.t,sub:(cat+': '+item.c).slice(0,80)+'...',
            action:function(c){return function(){_fiqhCat=c;SP('fiqh');};}(cat)});
        }
      });
    });
  }

  // بحث في السيرة
  if(_gsFilter==='all'&&typeof SEERAH_DATA!=='undefined'){
    Object.keys(SEERAH_DATA).forEach(function(cat){
      SEERAH_DATA[cat].forEach(function(ev){
        if(ev.title.includes(q)||ev.text.includes(q)){
          results.push({type:'seerah',tag:'🌙 سيرة',color:'#FF9F7F',
            title:ev.icon+' '+ev.title+' ('+ev.year+')',sub:ev.text.slice(0,80)+'...',
            action:function(){_seerahCat=cat;SP('seerah');}});
        }
      });
    });
  }

  if(cnt) cnt.textContent=results.length?'وُجد '+results.length+' نتيجة':'';
  if(!results.length){
    res.innerHTML='<div style="text-align:center;color:var(--tm);padding:2rem;font-size:.85rem;">لم يُعثر على نتائج لـ «'+_escHtml(q)+'»</div>';
    return;
  }
  res.innerHTML=results.slice(0,20).map(function(r){
    return '<div class="gs-result" onclick="this._act&&this._act()">'
      +'<span class="gs-tag" style="background:'+r.color+'22;color:'+r.color+';">'+r.tag+'</span>'
      +'<div style="font-size:.9rem;color:#f0d080;margin:.3rem 0;">'+hl(r.title)+'</div>'
      +'<div style="font-size:.78rem;color:var(--tm);">'+hl(r.sub)+'</div></div>';
  }).join('');
  // Attach actions after render
  var cards=res.querySelectorAll('.gs-result');
  results.slice(0,20).forEach(function(r,i){ if(cards[i]) cards[i]._act=r.action; });
}

// ══════════════════════════════════════════════════
// 🔔 EXTERNAL NOTIFICATIONS (Service Worker + Push)
// ══════════════════════════════════════════════════
var _notifSettings={
  prayer:true, fajr:true, dhuhr:true, asr:true, maghrib:true, isha:true,
  morning_dikr:true, evening_dikr:true, friday:true
};
try{ var _ns=JSON.parse(localStorage.getItem('nq_notif_settings')||'null'); if(_ns) _notifSettings=_ns; }catch(e){}
function saveNotifSettings(){ try{localStorage.setItem('nq_notif_settings',JSON.stringify(_notifSettings));}catch(e){} }

var _swReg=null;
function registerSW(){
  if(!('serviceWorker' in navigator)) return Promise.reject('no sw');
  if(_swReg) return Promise.resolve(_swReg);
  return Promise.race([
    navigator.serviceWorker.ready,
    new Promise(function(_,rej){ setTimeout(function(){ rej('sw timeout'); },4000); })
  ]).then(function(reg){ _swReg=reg; return reg; });
}

function requestNotifPerm(){
  Notification.requestPermission().then(function(perm){
    buildNotifs();
    if(perm==='granted') scheduleAllNotifs();
  });
}

function scheduleNotif(delay,title,body,tag){
  if(!_swReg||!_swReg.active) return;
  _swReg.active.postMessage({type:'SCHEDULE_NOTIF',delay:delay,title:title,body:body,tag:tag,
    icon:'data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><text y=".9em" font-size="90">🌙</text></svg>'});
}

function scheduleAllNotifs(){
  if(Notification.permission!=='granted'||!_swReg) return;
  var now=new Date();
  // أذكار الصباح — 6 صباحاً
  if(_notifSettings.morning_dikr){
    var morn=new Date(now); morn.setHours(6,0,0,0);
    if(morn<=now) morn.setDate(morn.getDate()+1);
    scheduleNotif(morn-now,'🌅 أذكار الصباح','حان وقت أذكار الصباح — ابدأ يومك بذكر الله','morning_dikr');
  }
  // أذكار المساء — 4 مساءً
  if(_notifSettings.evening_dikr){
    var evn=new Date(now); evn.setHours(16,0,0,0);
    if(evn<=now) evn.setDate(evn.getDate()+1);
    scheduleNotif(evn-now,'🌆 أذكار المساء','حان وقت أذكار المساء — أختم يومك بذكر الله','evening_dikr');
  }
  // صلاة الجمعة — تذكير كل جمعة 11:30
  if(_notifSettings.friday){
    var fri=new Date(now);
    var daysUntilFri=(5-fri.getDay()+7)%7||7;
    fri.setDate(fri.getDate()+daysUntilFri);
    fri.setHours(11,30,0,0);
    scheduleNotif(fri-now,'🕌 تذكير الجمعة','لا تنسَ صلاة الجمعة — استعد وتطهّر وبكّر','friday');
  }
  // صلوات بناءً على مواقيت محفوظة
  var savedPrayers=null;
  try{ savedPrayers=JSON.parse(localStorage.getItem('nq_prayer_times')||'null'); }catch(e){}
  if(savedPrayers){
    var prayerMap={fajr:'الفجر',dhuhr:'الظهر',asr:'العصر',maghrib:'المغرب',isha:'العشاء'};
    Object.keys(prayerMap).forEach(function(k){
      if(_notifSettings[k]&&savedPrayers[k]){
        var parts=savedPrayers[k].split(':');
        var pt=new Date(now); pt.setHours(parseInt(parts[0]),parseInt(parts[1]||0),0,0);
        if(pt<=now) pt.setDate(pt.getDate()+1);
        var delay=pt-now;
        if(delay<86400000)
          scheduleNotif(delay,'🕌 حان وقت صلاة '+prayerMap[k],'الله أكبر الله أكبر — حيّ على الصلاة',k);
      }
    });
  }
}

// Save prayer times when they load for use by SW
var _origUpdatePT=window.updatePrayerDisplay;
(function(){
  var _origFetchP=window.fetchPrayerTimes;
  // Hook to save prayer times after they're fetched
  var _savedTimes=false;
  setInterval(function(){
    if(_savedTimes) return;
    var fajrEl=document.getElementById('pt-fajr');
    if(fajrEl&&fajrEl.textContent&&fajrEl.textContent!=='--:--'){
      var times={};
      ['fajr','dhuhr','asr','maghrib','isha'].forEach(function(p){
        var el=document.getElementById('pt-'+p);
        if(el) times[p]=el.textContent;
      });
      if(times.fajr&&times.fajr!=='--:--'){
        localStorage.setItem('nq_prayer_times',JSON.stringify(times));
        _savedTimes=true;
        /* no auto schedule on load */ if(Notification.permission==='granted' && localStorage.getItem('nq_notif_on')==='1') scheduleAllNotifs();
      }
    }
  },3000);
})();

function buildNotifs(){
  var permBox=document.getElementById('notifs-permission-box');
  var grantBox=document.getElementById('notifs-granted-box');
  var list=document.getElementById('notifs-list');
  if(!list) return;
  var perm=('Notification' in window)?Notification.permission:'denied';
  if(permBox) permBox.style.display=perm==='granted'?'none':'block';
  if(grantBox) grantBox.style.display=perm==='granted'?'block':'none';

  // Register SW when user opens notif page
  if('serviceWorker' in navigator && !_swReg){
    registerSW().then(function(){ if(perm==='granted') scheduleAllNotifs(); }).catch(function(){});
  }

  var items=[
    {key:'prayer',    ico:'🕌', t:'أذان الصلوات',      s:'تنبيه لكل صلاة في وقتها'},
    {key:'fajr',      ico:'🌅', t:'الفجر',             s:'تنبيه خاص لصلاة الفجر'},
    {key:'dhuhr',     ico:'☀️', t:'الظهر',             s:'تنبيه صلاة الظهر'},
    {key:'asr',       ico:'🌤', t:'العصر',             s:'تنبيه صلاة العصر'},
    {key:'maghrib',   ico:'🌅', t:'المغرب',            s:'تنبيه صلاة المغرب'},
    {key:'isha',      ico:'🌙', t:'العشاء',            s:'تنبيه صلاة العشاء'},
    {key:'morning_dikr',ico:'🌄',t:'أذكار الصباح',    s:'تذكير يومي الساعة 6:00 صباحاً'},
    {key:'evening_dikr',ico:'🌆',t:'أذكار المساء',    s:'تذكير يومي الساعة 4:00 مساءً'},
    {key:'friday',    ico:'🕋', t:'تذكير الجمعة',     s:'تذكير كل جمعة 11:30 صباحاً'}
  ];

  list.innerHTML=items.map(function(it){
    var on=_notifSettings[it.key];
    return '<div style="background:rgba(13,59,46,.4);border:1px solid rgba(201,168,76,.15);border-radius:14px;padding:.9rem 1rem;margin-bottom:.5rem;display:flex;justify-content:space-between;align-items:center;">'
      +'<div style="display:flex;align-items:center;gap:.7rem;">'
      +'<span style="font-size:1.3rem;">'+it.ico+'</span>'
      +'<div><div style="font-size:.9rem;color:#f0d080;">'+it.t+'</div>'
      +'<div style="font-size:.72rem;color:var(--tm);">'+it.s+'</div></div></div>'
      +'<div class="atoggle'+(on?' on':'')+'" data-key="'+it.key+'" onclick="toggleNotifItem(this)"'
      +' style="width:44px;height:24px;background:'+(on?'rgba(201,168,76,.3)':'rgba(201,168,76,.1)')+';border:1px solid rgba(201,168,76,'+(on?'.5':'.2')+');border-radius:50px;cursor:pointer;position:relative;flex-shrink:0;">'
      +'<div style="width:18px;height:18px;background:'+(on?'#C9A84C':'rgba(201,168,76,.4)')+';border-radius:50%;position:absolute;top:2px;'+(on?'left':'right')+':2px;transition:all .3s;"></div>'
      +'</div></div>';
  }).join('');

  if(perm==='granted'){
    list.innerHTML+='<button onclick="scheduleAllNotifs();alert(\'✅ تم جدولة الإشعارات\')" style="width:100%;background:linear-gradient(135deg,rgba(201,168,76,.2),rgba(201,168,76,.08));border:1px solid rgba(201,168,76,.3);color:var(--gold);padding:.7rem;border-radius:12px;font-family:Tajawal,sans-serif;font-size:.88rem;cursor:pointer;margin-top:.5rem;">🔔 تفعيل وجدولة الإشعارات الآن</button>';
  }
}

function toggleNotifItem(el){
  var key=el.dataset.key;
  _notifSettings[key]=!_notifSettings[key];
  saveNotifSettings();
  buildNotifs.call(null);
  // re-render
  var list=document.getElementById('notifs-list');
  if(list){ document.getElementById('notifs-list').innerHTML=''; buildNotifs(); }
  /* no auto schedule on load */ if(Notification.permission==='granted' && localStorage.getItem('nq_notif_on')==='1') scheduleAllNotifs();
}

// Auto-init notifications on page load if already granted
(function(){
  if(typeof Notification!=='undefined'&&Notification.permission==='granted'){
    registerSW().then(function(){ scheduleAllNotifs(); }).catch(function(){});
  }
})();


