window.qaSendMsg=function(){
  if(_busy)return;
  var inp=document.getElementById('qa-inp'),btn=document.getElementById('qa-send');
  if(!inp)return;
  var txt=inp.value.trim();if(!txt)return;
  var sg=document.getElementById('qa-suggestions');if(sg)sg.style.display='none';
  _add('user',txt);
  _msgs.push({role:'user',content:txt});
  inp.value='';inp.style.height='auto';
  _busy=true;if(btn)btn.disabled=true;

  // ── typing indicator ──
  var tp=_add('bot','',true);

  // ── streaming fetch ──
  fetch(HUDA_BACKEND_URL+'/ai/chat/stream',{
    method:'POST',
    headers:{'Content-Type':'application/json'},
    body:JSON.stringify({ messages:_msgs.slice(-12) })
  })
  .then(function(r){
    if(!r.ok) return r.json().then(function(e){ throw e; });
    // ── remove typing bubble, create streaming bubble ──
    if(tp) tp.remove();
    var el=document.getElementById('qa-messages');
    var d=document.createElement('div');
    d.className='qa-msg qa-msg-bot';
    var bubble=document.createElement('div');
    bubble.className='qa-bubble';
    bubble.innerHTML='<p></p>';
    d.innerHTML='<div class="qa-avatar">🌙</div>';
    d.appendChild(bubble);
    el.appendChild(d);
    el.scrollTop=el.scrollHeight;

    var reader=r.body.getReader();
    var decoder=new TextDecoder();
    var fullText='';
    var p=bubble.querySelector('p');

    function pump(){
      return reader.read().then(function(result){
        if(result.done){
          // ── stream finished — add validation badge ──
          if(typeof HudaValidation!=='undefined'&&typeof _addWithBadge!=='undefined'){
            var score=HudaValidation.trustScore(fullText);
            var badge=HudaValidation.wrapWithBadge('',score);
            var badgeEl=document.createElement('div');
            badgeEl.innerHTML=badge;
            bubble.appendChild(badgeEl);
          }
          _msgs.push({role:'assistant',content:fullText});
          el.scrollTop=el.scrollHeight;
          return;
        }
        var chunk=decoder.decode(result.value,{stream:true});
        var lines=chunk.split('\n');
        lines.forEach(function(line){
          if(!line.startsWith('data:')) return;
          var data=line.slice(5).trim();
          if(data==='[DONE]') return;
          try{
            var json=JSON.parse(data);
            var delta=(json.choices&&json.choices[0]&&json.choices[0].delta&&json.choices[0].delta.content)||'';
            if(delta){
              fullText+=delta;
              // ── render markdown-like formatting ──
              var html=fullText
                .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
                .replace(/\*\*(.*?)\*\*/g,'<strong>$1</strong>')
                .replace(/﴿(.*?)﴾/g,'<span style="color:#C9A84C;font-family:Scheherazade New,serif;font-size:1.1em;">﴿$1﴾</span>')
                .replace(/«(.*?)»/g,'<em style="color:#a8d4b4;">«$1»</em>')
                .replace(/\n\n/g,'</p><p>').replace(/\n/g,'<br>');
              p.innerHTML=html;
              el.scrollTop=el.scrollHeight;
            }
          }catch(e){}
        });
        return pump();
      });
    }
    return pump();
  })
  .catch(function(e){
    // Fallback: طلب غير متدفق
    return fetch(HUDA_BACKEND_URL+'/ai/chat',{
      method:'POST',
      headers:{'Content-Type':'application/json'},
      body:JSON.stringify({ messages:_msgs.slice(-12) })
    }).then(function(r){
      if(!r.ok) return r.json().then(function(j){ throw j; });
      return r.json();
    }).then(function(j){
      if(tp) tp.remove();
      if(j && j.success && j.reply){
        _add('bot', j.reply);
        _msgs.push({role:'assistant',content:j.reply});
        return;
      }
      throw j || new Error('no reply');
    }).catch(function(err){
      if(tp) tp.remove();
      _msgs.pop();
      var msg = (err && (err.error || err.message)) || '';
      if(/Failed to fetch|NetworkError|Load failed/i.test(String(msg)) || !msg){
        _add('bot','⚠️ تعذّر الاتصال بالسيرفر.\nتأكد أن السيرفر يعمل:\ncd backend && npm start\nوالرابط في config.js صحيح (مثل http://192.168.1.73:3000/api)');
      } else {
        _add('bot','⚠️ '+msg+'\nإن استمرت المشكلة: غيّر GROQ_MODELS إلى openai/gpt-oss-20b في backend/.env');
      }
    });
  })
  .finally(function(){_busy=false;if(btn)btn.disabled=false;if(inp)inp.focus();});
}

