// 🔍 SEARCH ENGINE — بحث شامل في القرآن والأحاديث والتفسير
// ════════════════════════════════════════════════════════════════

var _qsFilter = 'quran';
var _qsLastQuery = '';

function qsSetFilter(filter, btn){
  _qsFilter = filter;
  document.querySelectorAll('.comm-filter').forEach(function(b){ b.classList.remove('on'); });
  if(btn) btn.classList.add('on');
  qsSearch(_qsLastQuery);
}

function qsSearch(query){
  _qsLastQuery = (query||'').trim();
  var resultsEl = document.getElementById('qs-results');
  var statsEl   = document.getElementById('qs-stats');
  if(!resultsEl) return;

  if(!_qsLastQuery){
    resultsEl.innerHTML = '<div style="text-align:center;padding:2rem;color:var(--tm);font-size:.9rem;">اكتب كلمة للبحث في القرآن الكريم</div>';
    if(statsEl) statsEl.textContent = '';
    return;
  }

  if(statsEl) statsEl.textContent = '⏳ جارٍ البحث...';
  var q = _qsLastQuery;
  var token = (++window._qsToken || (window._qsToken = 1));

  // استخدم الفهرس المحلي دائمًا (مستقر ولا يختفي)
  function renderMatches(matches){
    if (token !== window._qsToken) return; // تجاهل استجابة قديمة
    matches = matches || [];
    if(statsEl) statsEl.textContent = matches.length ? ('وُجد '+matches.length+' نتيجة لـ «'+q+'»') : ('لا نتائج لـ «'+q+'»');
    if(!matches.length){
      resultsEl.innerHTML = '<div style="text-align:center;padding:2rem;color:var(--tm);">لا توجد نتائج — جرّب كلمة أخرى</div>';
      return;
    }
    resultsEl.innerHTML = matches.slice(0, 50).map(function(m){
      var sName = (m.surah && (m.surah.name || m.surah.englishName)) || '';
      var sn = (m.surah && m.surah.number) || '';
      var an = m.numberInSurah || '';
      var txt = String(m.text||'');
      try {
        var re = new RegExp(q.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'), 'g');
        txt = txt.replace(re, function(x){ return '<mark style="background:rgba(201,168,76,.35);color:#f0d080;border-radius:3px;padding:0 2px;">'+x+'</mark>'; });
      } catch(e){}
      return '<div class="qs-card" style="background:rgba(13,59,46,.4);border:1px solid rgba(201,168,76,.18);border-radius:14px;padding:.9rem;margin-bottom:.65rem;cursor:pointer;" onclick="if(window.HudaMushaf&&HudaMushaf.goAyah){SP(\'mushaf\');HudaMushaf.goAyah('+sn+','+an+');}">' +
        '<div style="color:var(--gold);font-size:.8rem;margin-bottom:.3rem;font-weight:700;">📖 '+sName+' — آية '+an+'</div>'+
        '<div style="color:#e8dfc0;font-family:\'Amiri Quran\',\'Scheherazade New\',serif;font-size:1.08rem;line-height:1.95;">'+txt+'</div>'+
      '</div>';
    }).join('');
  }

  if (window.HudaQuran && typeof HudaQuran.fetch === 'function') {
    HudaQuran.fetch('https://api.alquran.cloud/v1/search/'+encodeURIComponent(q)+'/all/ar')
      .then(function(r){ return r.json(); })
      .then(function(data){
        var matches = (data && data.data && data.data.matches) || [];
        renderMatches(matches);
      })
      .catch(function(){
        if (token !== window._qsToken) return;
        if(statsEl) statsEl.textContent = '';
        resultsEl.innerHTML = '<div style="text-align:center;color:var(--tm);padding:1rem;">⚠️ تعذّر البحث</div>';
      });
  } else {
    _qsSearchApi(q);
  }
}

function _qsSearchApi(q){
  var resultsEl = document.getElementById('qs-results');
  var statsEl   = document.getElementById('qs-stats');
  if(statsEl) statsEl.textContent = '⏳ جارٍ البحث...';
  HudaQuran.fetch('https://api.alquran.cloud/v1/search/'+encodeURIComponent(q)+'/all/ar')
    .then(function(r){ return r.json(); })
    .then(function(data){
      var matches = (data.data && data.data.matches) || [];
      if(statsEl) statsEl.textContent = 'وُجد '+matches.length+' نتيجة لـ "'+q+'"';
      if(!matches.length){
        resultsEl.innerHTML = '<div style="text-align:center;padding:2rem;color:var(--tm);">لا توجد نتائج</div>';
        return;
      }
      resultsEl.innerHTML = matches.slice(0,30).map(function(m){
        var txt = _escHtml(m.text||'').replace(
          new RegExp(_escRegex(q),'g'),
          '<mark style="background:rgba(201,168,76,.3);color:#f0d080;border-radius:3px;padding:0 2px;">'+_escHtml(q)+'</mark>'
        );
        return '<div style="background:rgba(13,59,46,.35);border:1px solid rgba(201,168,76,.15);border-radius:14px;padding:.9rem;margin-bottom:.7rem;">' +
          '<div style="color:var(--gold);font-size:.8rem;margin-bottom:.3rem;">📖 سورة '+(m.surah&&m.surah.englishName||'')+' — آية '+(m.numberInSurah||'')+'</div>'+
          '<div style="color:#e8dfc0;font-family:\'Scheherazade New\',serif;font-size:1.05rem;line-height:1.9;">'+txt+'</div>'+
        '</div>';
      }).join('');
    })
    .catch(function(){
      if(resultsEl) resultsEl.innerHTML = '<div style="text-align:center;color:var(--tm);padding:1rem;">⚠️ تعذّر البحث — تحقق من الاتصال</div>';
    });
}

