// ════════════════════════════════════════════════════════════════
// 🛡️ VALIDATION ENGINE — نظام التحقق من الإجابات
// ════════════════════════════════════════════════════════════════

var HudaValidation = (function(){
  // كلمات تدل على إنشاء نص ديني بدلاً من الشرح
  var FORBIDDEN_PATTERNS = [
    /قال الله تعالى.*?[»"]/,
    /قال رسول الله.*?[»"]/,
    /حديث.*?[»"]/,
    /روى.*?عن.*?[»"]/
  ];

  // مواضيع خارج نطاق التطبيق
  var OFF_TOPIC = ['سياسة','أخبار','رياضة','تكنولوجيا','طبخ','موسيقى','أفلام'];

  function isOffTopic(q){
    var ql = q || '';
    for(var i=0;i<OFF_TOPIC.length;i++){
      if(ql.indexOf(OFF_TOPIC[i])>-1) return true;
    }
    return false;
  }

  function hasForbiddenGeneration(answer){
    for(var i=0;i<FORBIDDEN_PATTERNS.length;i++){
      if(FORBIDDEN_PATTERNS[i].test(answer)) return true;
    }
    return false;
  }

  // التحقق من وجود مصدر في الإجابة
  function hasSource(answer){
    var src = ['سورة','آية','صحيح البخاري','صحيح مسلم','أبو داود','الترمذي','النسائي',
               'ابن ماجه','أحمد','الموطأ','فتح الباري','القرآن','الحديث'];
    for(var i=0;i<src.length;i++){
      if(answer && answer.indexOf(src[i])>-1) return true;
    }
    return false;
  }

  // نقاط ثقة الإجابة
  function trustScore(answer){
    var score = 50;
    if(hasSource(answer)) score += 35;
    if(answer && answer.length > 200) score += 10;
    if(hasForbiddenGeneration(answer)) score -= 40;
    if(score < 0) score = 0;
    if(score > 99) score = 99;
    return score;
  }

  // رسالة "لا أعلم"
  var NO_ANSWER_MSG = '❌ لا توجد إجابة موثوقة لهذا السؤال في قاعدة بياناتنا.\n\nنرجو مراجعة عالم متخصص أو موقع موثوق مثل islamqa.info';

  return {
    isOffTopic: isOffTopic,
    hasForbiddenGeneration: hasForbiddenGeneration,
    hasSource: hasSource,
    trustScore: trustScore,
    NO_ANSWER: NO_ANSWER_MSG,

    // يلف الإجابة ببادج نسبة الثقة
    wrapWithBadge: function(html, score){
      var color = score >= 80 ? '#4caf7d' : score >= 55 ? '#e6a817' : '#e05b5b';
      var label = score >= 80 ? 'موثوقة' : score >= 55 ? 'متوسطة' : 'تحتاج مراجعة';
      return html +
        '<div style="margin-top:.9rem;display:flex;align-items:center;gap:.5rem;padding:.5rem .8rem;background:rgba(0,0,0,.25);border-radius:10px;border-right:3px solid '+color+';">' +
        '<span style="color:'+color+';font-size:.78rem;font-weight:700;">📊 نسبة الثقة: '+score+'%</span>' +
        '<span style="color:'+color+';font-size:.72rem;">('+label+')</span>' +
        '</div>' +
        '<div style="margin-top:.5rem;color:rgba(201,168,76,.5);font-size:.68rem;text-align:center;">⚠️ هذه الإجابة للاستئناس — يرجى مراجعة عالم للفتاوى</div>';
    }
  };
})();

